// Static component harness only, not an UPLY instance; no auth or DB connection.
import{build}from'esbuild';import{createServer}from'node:http';import{mkdtemp,writeFile,readFile,rm}from'node:fs/promises';import{tmpdir}from'node:os';import{join,resolve}from'node:path';import assert from'node:assert/strict';import{createRequire}from'node:module';
const require=createRequire(import.meta.url);const{chromium}=require('/home/yangzhen/.local/share/uply-browser-tools/node_modules/playwright-core');
const dir=await mkdtemp(join(tmpdir(),'b2a-ui-'));let page,server;const results=[];
try{
 await build({stdin:{contents:`import React from 'react';import{createRoot}from'react-dom/client';import{ProvisioningForm}from'./src/features/development-execution/components/provisioning-form';window.calls=0;window.setResult=(x)=>{window.response=x};window.response='VERIFY_REQUIRED';const q=new URLSearchParams(location.search);createRoot(document.getElementById('root')).render(<ProvisioningForm state={q.get('state')||'READY'}/>);`,resolveDir:process.cwd(),loader:'tsx'},bundle:true,outfile:join(dir,'app.js'),platform:'browser',jsx:'automatic',plugins:[{name:'isolated-action',setup(b){b.onResolve({filter:/provisioning.actions$/},()=>({path:'action',namespace:'fixture'}));b.onLoad({filter:/.*/,namespace:'fixture'},()=>({contents:`export async function provisionDevelopmentExecutionAction(){window.calls++;if(window.response==='THROW')throw Error('lost response');return{status:window.response,scope:'DISABLED'};}`,loader:'js'}));}}],logLevel:'silent'});
 const js=await readFile(join(dir,'app.js'));server=createServer((req,res)=>{if(req.url.startsWith('/app.js')){res.setHeader('Content-Type','text/javascript');res.end(js);}else{res.setHeader('Content-Type','text/html');res.end('<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><div id="root"></div><script src="/app.js"></script>');}});await new Promise(r=>server.listen(0,'127.0.0.1',r));const base=`http://127.0.0.1:${server.address().port}`;
 const browser=await chromium.connectOverCDP('http://127.0.0.1:9222');page=await browser.contexts()[0].newPage();
 await page.goto(base);await page.getByRole('button',{name:'创建开发执行身份'}).waitFor();await page.waitForFunction(()=>!document.querySelector('button').disabled);
 results.push({case:'ready enabled',pass:true});await page.evaluate(()=>{document.querySelector('button').click();document.querySelector('button').click();});await page.getByRole('status').filter({hasText:'已停止操作'}).waitFor();assert.equal(await page.evaluate(()=>window.calls),1);assert.equal(await page.getByRole('button').isDisabled(),true);results.push({case:'double click + UNKNOWN no retry',pass:true});
 await page.reload();await page.getByRole('status').filter({hasText:'已有提交记录'}).waitFor();assert.equal(await page.getByRole('button').isDisabled(),true);assert.equal(await page.evaluate(()=>window.calls),0);results.push({case:'reload retains local submission fence',pass:true});
 for(const state of ['BLOCKED','EXISTING']){await page.goto(base+'?state='+state);await page.getByRole('button').waitFor();assert.equal(await page.getByRole('button').isDisabled(),true);assert.equal(await page.evaluate(()=>window.calls),0);results.push({case:state+' disabled',pass:true});}
 await page.evaluate(()=>sessionStorage.clear());await page.goto(base);await page.waitForFunction(()=>!document.querySelector('button').disabled);await page.evaluate(()=>window.setResult('THROW'));await page.getByRole('button').click();await page.getByRole('status').filter({hasText:'结果不明确'}).waitFor();assert.equal(await page.evaluate(()=>window.calls),1);assert.equal(await page.getByRole('button').isDisabled(),true);results.push({case:'connection loss holds',pass:true});
 const dom=await page.locator('body').innerText();assert.doesNotMatch(dom,/service.role|password|refresh.token|actorId|tenantId|pgpass/i);results.push({case:'public UI no secrets/input controls',pass:(await page.locator('input,select,textarea').count())===0});assert.ok(results.every(r=>r.pass));
 await writeFile('docs/evidence/teaching-agent-stage-1f-r7c-b/b2a-ui-browser-tests.json',JSON.stringify({status:'PASS',tests:results,scope:'Actual React component and existing Chrome in static isolated harness; Server Action substituted. No live provisioning or authenticated route request.',currentDbWrites:0},null,2)+'\n');console.log(JSON.stringify({browserTests:results.length,passed:results.length,currentDbWrites:0}));
}finally{await page?.close();await new Promise(r=>server?server.close(r):r());await rm(dir,{recursive:true,force:true});}
process.exit(0);
